CREATE POLICY "rates_read_authenticated" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'rates');
CREATE POLICY "rates_insert_own" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'rates' AND auth.uid()::text = (storage.foldername(name))[1]);
CREATE POLICY "rates_update_own" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'rates' AND auth.uid()::text = (storage.foldername(name))[1]) WITH CHECK (bucket_id = 'rates' AND auth.uid()::text = (storage.foldername(name))[1]);
CREATE POLICY "rates_delete_own" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'rates' AND auth.uid()::text = (storage.foldername(name))[1]);